import sys; sys.path.insert(0,'/workspace/work')
import numpy as np, wave
def load(path):
    w=wave.open(path); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
    return d[0::2], d[1::2]
def sec_rms(L,R,bar_len=2.56):
    out=[]
    for i in range(int(len(L)/(bar_len*44100))+1):
        a=int(i*bar_len*44100); b=min(len(L),int((i+1)*bar_len*44100))
        if b-a<100: break
        out.append((i, round(float(np.sqrt((L[a:b]**2).mean())),4), round(float(np.sqrt((R[a:b]**2).mean())),4), round(float(max(np.abs(L[a:b]).max(),np.abs(R[a:b]).max())),3)))
    return out
