    L,R=load(sys.argv[1])
    print('dur %.2f'%(len(L)/44100),'peak %.3f'%max(np.abs(L).max(),np.abs(R).max()))
    for row in sec_rms(L,R): print(row)
    # stereo correlation
    print('corr', round(float(np.corrcoef(L,R)[0,1]),3))
