{"command": "cd /workspace && cat > work/synth.py <<'PY'
import numpy as np
SR=8363.0

def norm(x, peak=0.95):
    m=np.max(np.abs(x)); return x*(peak/m) if m>0 else x

def fe(x, n=12):
    x=x.copy(); n=min(n,len(x)//2)
    if n>0:
        x[:n]*=np.linspace(0,1,n); x[-n:]*=np.linspace(1,0,n)
    return x

def fft_lp(x, fc, order=2, rate=SR):
    X=np.fft.rfft(x); f=np.fft.rfftfreq(len(x),1/rate)
    return np.fft.irfft(X/(1+(f/fc)**(2*order)), len(x))

def fft_hp(x, fc, order=2, rate=SR):
    X=np.fft.rfft(x); f=np.fft.rfftfreq(len(x),1/rate)
    r=(f/fc)**(2*order)
    return np.fft.irfft(X*(r/(1+r)), len(x))

def noise(n, seed):
    return np.random.default_rng(seed).standard_normal(n)

def pulse_loop(freq, duty=0.25, nharm=6, cycles=16, amp=0.9):
    L=int(round(cycles*SR/freq)); t=np.arange(L)/SR; f=cycles*SR/L
    x=np.zeros(L)
    for k in range(1,nharm+1):
        if f*k>SR/2*0.94: break
        x+=(2/(k*np.pi))*np.sin(np.pi*k*duty)*np.cos(2*np.pi*k*f*t)
    return norm(x,amp)

def pulse_detuned(freq, duty=0.25, nharm=6, cycles=16, amp=0.9, det=0.004):
    """two detuned pulses for width/beating"""
    L=int(round(cycles*SR/freq)); t=np.arange(L)/SR; f=cycles*SR/L
    x=np.zeros(L)
    for k in range(1,nharm+1):
        if f*k>SR/2*0.94: break
        a=(2/(k*np.pi))*np.sin(np.pi*k*duty)
        x+=a*(np.cos(2*np.pi*k*f*t)+0.7*np.cos(2*np.pi*k*f*(1+det)*t+k*0.4))
    return norm(x,amp)

def bass_oneshot(dur=0.42, freq=110.0, amp=0.95, decay=0.19, drive=1.5, nharm=32, lp=2600):
    n=int(dur*SR); t=np.arange(n)/SR
    x=np.zeros(n)
    for k in range(1,nharm+1):
        if freq*k>SR/2*0.9: break
        x+=(1.0/k)*np.sin(2*np.pi*k*freq*t)
    x=x+0.6*np.sign(np.sin(2*np.pi*freq*t))*np.exp(-t/(decay*0.5))
    x=fft_lp(x, 2400, 2)
    env=(1-np.exp(-t/0.0035))*np.exp(-t/decay)
    # small sustain tail so short notes still sound
    env=np.maximum(env, 0.10*np.exp(-t/(decay*2.2))*(1-np.exp(-t/0.0035)))
    x*=env
    x+=0.25*fft_lp(noise(n,91),1800)*np.exp(-t/0.003)
    x=np.tanh(drive*x)
    return fe(norm(x,amp),6)

def kick(dur=0.42, f0=175, f1=48, drop=0.030, decay=0.115, amp=0.97, click=0.45, drive=1.7):
    n=int(dur*SR); t=np.arange(n)/SR
    f=f1+(f0-f1)*np.exp(-t/drop)
    ph=2*np.pi*np.cumsum(f)/SR
    x=np.sin(ph)*np.exp(-t/decay)+0.35*np.sin(2*ph)*np.exp(-t/(decay*0.5))
    ck=fft_lp(noise(n,93),5000)*np.exp(-t/0.0025)
    x=np.tanh(drive*(x+click*ck))
    return fe(norm(x,amp),6)

def snare(dur=0.26, tone=185, amp=0.95, seed=95):
    n=int(dur*SR); t=np.arange(n)/SR
    body=(np.sin(2*np.pi*tone*t)*np.exp(-t/0.05)+0.45*np.sin(2*np.pi*tone*1.62*t)*np.exp(-t/0.032))
    nz=fft_hp(noise(n,seed),1600); nz=fft_lp(nz,7000)
    nz*=np.exp(-t/0.085)
    cl=np.zeros(n)
    for off,dc in [(0.0,0.010),(0.009,0.010),(0.019,0.045)]:
        i=int(off*SR); m=n-i
        cl[i:]+=noise(m,seed+1)*np.exp(-np.arange(m)/(SR*dc))
    cl=fft_hp(cl,1100); cl=fft_lp(cl,5000)
    x=0.55*body+0.85*nz+0.55*cl
    return fe(norm(x,amp),6)

def hat(dur=0.055, decay=0.013, amp=0.85, seed=97, fc=6800):
    n=int(dur*SR); t=np.arange(n)/SR
    x=fft_hp(noise(n,seed),fc)*np.exp(-t/decay)
    return fe(norm(x,amp),4)

def openhat(dur=0.30, decay=0.075, amp=0.8, seed=99, fc=5200):
    n=int(dur*SR); t=np.arange(n)/SR
    x=fft_hp(noise(n,seed),fc)*np.exp(-t/decay)
    x=fft_lp(x,11000)
    return fe(norm(x,amp),8)

def crash(dur=1.6, decay=0.55, amp=0.82, seed=101):
    n=int(dur*SR); t=np.arange(n)/SR
    x=fft_hp(noise(n,seed),3000)*np.exp(-t/decay)
    x=fft_lp(x,12000)
    return fe(norm(x,amp),16)

def tom(dur=0.3, f0=300, f1=125, amp=0.9, seed=103):
    n=int(dur*SR); t=np.arange(n)/SR
    f=f1+(f0-f1)*np.exp(-t/0.055)
    ph=2*np.pi*np.cumsum(f)/SR
    x=np.sin(ph)*np.exp(-t/0.12)+0.12*fft_hp(noise(n,seed),1500)*np.exp(-t/0.025)
    return fe(norm(x,amp),6)

def zap(dur=0.24, amp=0.8):
    n=int(dur*SR); t=np.arange(n)/SR
    f=3600*np.exp(-t/0.045)+140
    ph=2*np.pi*np.cumsum(f)/SR
    x=np.sin(ph)*np.exp(-t/0.09)
    x+=0.25*fft_hp(noise(n,105),2000)*np.exp(-t/0.05)
    return fe(norm(x,amp),6)

def riser(dur=1.7, amp=0.8, seed=107):
    n=int(dur*SR); t=np.arange(n)/SR
    nz=noise(n,seed); x=np.zeros(n); blk=512
    for i in range(0,n,blk):
        seg=nz[i:i+blk]
        cent=300*(20**(i/max(n-1,1)))
        X=np.fft.rfft(seg); f=np.fft.rfftfreq(len(seg),1/SR)
        H=np.exp(-0.5*((np.log(f+1)-np.log(cent))/0.45)**2)
        x[i:i+blk]=np.fft.irfft(X*H,len(seg))
    x*=np.linspace(0,1,n)**2
    return fe(norm(x,amp),20)

def bell(freq=440.0, dur=1.25, amp=0.75):
    n=int(dur*SR); t=np.arange(n)/SR
    parts=[(1.0,1.0,0.62),(2.0,0.42,0.36),(2.76,0.30,0.22),(4.07,0.10,0.12),(5.43,0.05,0.07)]
    x=np.zeros(n)
    for mul,a,d in parts:
        if freq*mul>SR/2*0.94: continue
        x+=a*np.sin(2*np.pi*freq*mul*t)*np.exp(-t/d)
    x+=0.08*fft_hp(noise(n,109),3000)*np.exp(-t/0.01)
    return fe(norm(x,amp),10)

def pad(root, intervals, dur=1.52, amp=0.72, attack=0.13, release=0.30, nharm=11, det=0.0035):
    n=int(dur*SR); t=np.arange(n)/SR
    x=np.zeros(n)
    for iv in intervals:
        f=root*2**(iv/12)
        for d in (-det,0.0,det):
            ff=f*(1+d)
            for k in range(1,nharm+1):
                if ff*k>SR/2*0.9: break
                x+=(1.0/k**1.3)*np.sin(2*np.pi*k*ff*t+k*0.5)
    x=fft_hp(x,70,1); x=fft_lp(x,2400,1)
    e=np.ones(n)
    a=int(attack*SR); e[:a]=np.linspace(0,1,a)**1.3
    r=int(release*SR); e[-r:]*=np.linspace(1,0,r)**1.15
    e*=1+0.06*np.sin(2*np.pi*0.75*t)
    x*=e
    return norm(x,amp)

def sub_bass_loop(freq=55.0, cycles=32, amp=0.9):
    L=int(round(cycles*SR/freq)); t=np.arange(L)/SR; f=cycles*SR/L
    x=np.sin(2*np.pi*f*t)+0.35*np.sin(2*np.pi*2*f*t)+0.12*np.sin(2*np.pi*3*f*t)
    return norm(x,amp)
