def bass_bar(T,bar,chord,vol=62,style='drive',im=None):
    r=BASS_ROOT[chord]; r12=tr(r,12); fifth=tr(r,7); f12=tr(fifth,12); third=tr(r,3)
    row0=bar*16
    if style=='drive':
        for i,n in enumerate([r,r,r12,r,fifth,r,r12,fifth]):
            T.note(row0+i*2, CH['bass'], n, im['bass'], vol)
    elif style=='walk':
        for i,n in enumerate([r,r12,fifth,r12,r,fifth,third,fifth]):
            T.note(row0+i*2, CH['bass'], n, im['bass'], vol)
    elif style=='octave':
        for i,n in enumerate([r,r12,r,r12,r,r12,fifth,f12]):
            T.note(row0+i*2, CH['bass'], n, im['bass'], vol)
    elif style=='sparse':
        for i,n in enumerate([r,r12,fifth,tr(r,10)]):
            T.note(row0+i*4, CH['bass'], n, im['bass'], vol)
    elif style=='pulse8':
