    seq = base+base[-2:0:-1] if mode=='updown' else (base if mode=='up' else base[::-1])
    row0=bar*16
    for i in range(start,stop,step):
        T.note(row0+i, ch, seq[i%len(seq)], im_global['arp12'] if ch==CH['arp'] else im_global['arp12'], vol)

