}
def make_instruments():
    cfg=CFG
    ins=[]
    def add(name,data,relnote=12):
        c=cfg[name]
        ins.append(dict(name=name,data=data,vol=c['vol'],pan=c['pan'],relnote=relnote,
                        loop=(name in ('lead','lead2','echo','arp','arp2'))))
    add('lead',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.25,nharm=26,cycles=32,amp=0.9))
    add('lead2', S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=22,cycles=40,amp=0.85))
    add('echo',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.25,nharm=26,cycles=32,amp=0.9))
    add('arp',   S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=18,cycles=40,amp=0.8))
    add('arp2',  S2.saw_loop(rate=RATE,f0=F0,nharm=24,cycles=32,amp=0.75,tilt=1.2))
    add('bass',  S2.bass_oneshot(rate=RATE,f0=F0,dur=0.40,amp=0.95,decay=0.16))
    add('kick',  S2.kick(rate=RATE,dur=0.34,f0=190,f1=47,decay=0.105))
    add('snare', S2.snare(rate=RATE,dur=0.24,tone=195))
    add('hatC',  S2.hat(rate=DRATE,dur=0.055,decay=0.013), relnote=24)
    add('hatO',  S2.openhat(rate=DRATE,dur=0.26,decay=0.065), relnote=24)
    add('crash', S2.crash(rate=DRATE,dur=1.5,decay=0.5), relnote=24)
    add('tom',   S2.tom(rate=RATE,dur=0.28,f0=330,f1=130))
    add('zap',   S2.zap(rate=RATE,dur=0.10,amp=0.7))
    add('riser', S2.riser(rate=RATE,dur=1.7))
    add('bell',  S2.bell(rate=RATE,f=F0,dur=1.15,amp=0.72))
    for ch,(root,ivs) in PADS.items():
        add('pad'+ch+'L', S2.pad(root,ivs,rate=RATE,dur=1.62,amp=0.72,det=0.0035))
        add('pad'+ch+'R', S2.pad(root,ivs,rate=RATE,dur=1.62,amp=0.72,det=-0.0045))
