def hat_bar(T,bar,mode='8ths',vol=30):
    row0=bar*16
    if mode=='8ths':
        for i in range(0,16,2):
            inst=INS['hatO'] if i in (6,14) else INS['hatC']
            T.note(row0+i, CH['hats'], 'C-4', inst, vol if i%4==0 else vol-7)
    elif mode=='16ths':
        for i in range(16):
            inst=INS['hatO'] if i in (6,14) else INS['hatC']
            T.note(row0+i, CH['hats'], 'C-4', inst, (vol if i%4==0 else vol-9)-(4 if i%2 else 0))
    elif mode=='off':
        for i in range(16):
