        for i in range(start,16): T.note(row0+i, CH['snare'], 'C-4', INS['snare'], vol if i%2==0 else vol-9)
    elif kind=='snare16':
        for i in range(start,16): T.note(row0+i, CH['snare'], 'C-4', INS['snare'], vol if i%4==0 else vol-11)
    elif kind=='toms':
        seq=[('C-4',vol),('E-4',vol-4),('G-4',vol-7),('C-4',vol-2)]
        for k,i in enumerate(range(start,16)):
            n,v=seq[k%4]; T.note(row0+i, CH['snare'], n, INS['tom'], v)
    elif kind=='mix':
        T.note(row0+start, CH['snare'], 'C-4', INS['snare'], vol)
        T.note(row0+start+2, CH['snare'], 'C-4', INS['snare'], vol-8)
        T.note(row0+start+3, CH['snare'], 'E-4', INS['tom'], vol-6)
        T.note(row0+14, CH['snare'], 'G-4', INS['tom'], vol-3)
        T.note(row0+15, CH['snare'], 'C-4', INS['tom'], vol)

