def N(s):
    if isinstance(s,int): return s
    i=1; pc=PC[s[0]]
    if i<len(s) and s[i] in '#b':
        pc += 1 if s[i]=='#' else -1; i+=1
    rest=s[i:]
    if rest.startswith('-'): rest=rest[1:]
    return int(rest)*12+pc+1
def nm(b):
    v=int(b)-1; return NAMES[v%12]+str(v//12)
def tr(s,semis): return nm(N(s)+semis)

