    bell_row(T,0,'A-4',26); bell_row(T,8,'E-5',24); bell_row(T,16,'C-5',26); bell_row(T,24,'A-4',24)
    bell_row(T,16,'F-4',20); bell_row(T,24,'C-5',20)
    for b in (1,2,3): arp_bar(T,b,PROG_A[b],vol=18+b*4,step=2,mode='updown')
    hat_bar(T,1,'sparse',vol=18); hat_bar(T,2,'off',vol=22); hat_bar(T,3,'8ths',vol=26)
    kick_bar(T,2,[0,8],vol=36); kick_bar(T,3,[0,4,8,12],vol=42)
    snare_bar(T,3,[4,12],vol=34)
    riser_row(T,32,vol=26); crash_row(T,0,vol=30)
    for i,(r,n) in enumerate([(48,'A-5'),(50,'B-5'),(52,'C-6'),(54,'D-6'),(56,'E-6'),(58,'F-6'),(60,'E-6'),(62,'D-6')]):
        T.note(r,CH['lead'],n,INS['lead'],38+i)
    pats.append(T.p)

    # P1 A
    T=Tr()
    for b,ch in enumerate(PROG_A):
        pad_bar(T,b,ch,vol=28)
        bass_bar(T,b,ch,vol=44)
        arp_bar(T,b,ch,vol=24,inst=INS['arp'],pan_sweep=[(0,0x40),(8,0xC0)] if b%2==0 else [(0,0xC0),(8,0x40)])
        drums(T,b,'basic','8ths')
    crash_row(T,0,vol=34)
    lead_phrase(T,themeA(),vol=52,vib=[(6,0x44),(24,0x44),(40,0x44),(56,0x44)])
    fill(T,3,'snare',vol=34,start=14)
    pats.append(T.p)

    # P2 A variation
    T=Tr()
    for b,ch in enumerate(PROG_A):
        pad_bar(T,b,ch,vol=28)
        bass_bar(T,b,ch,vol=44,style='oct' if b==1 else '8ths')
        arp_bar(T,b,ch,vol=24,inst=INS['arp'],step=1 if b>0 else 2)
        arp_bar(T,b,ch,vol=18,mode='down',ch=CH['arp2'],octv=1,inst=INS['arp2'])
        drums(T,b,'drive' if b in (1,3) else 'basic','16ths' if b==3 else '8ths')
    crash_row(T,0,vol=34); crash_row(T,32,vol=26)
    lead_phrase(T,themeA_var(),vol=52)
    fill(T,3,'mix',vol=40)
    pats.append(T.p)

    # P3 B
    T=Tr()
    for b,ch in enumerate(PROG_B):
        pad_bar(T,b,ch,vol=30); bass_bar(T,b,ch,vol=44)
        arp_bar(T,b,ch,vol=24,inst=INS['arp'],step=1)
        drums(T,b,'basic','8ths')
    crash_row(T,0,vol=34)
    lead_phrase(T,themeB(),vol=52,vib=[(14,0x44),(30,0x44),(46,0x44),(60,0x44)])
    fill(T,3,'snare',vol=36,start=14)
    pats.append(T.p)

    # P4 breakdown
    T=Tr()
    for b,ch in enumerate(PROG_A):
        pad_bar(T,b,ch,vol=44)
        arp_bar(T,b,ch,vol=20,mode='updown' if b%2 else 'up',step=1)
    crash_row(T,0,vol=28)
    for r,n in [(0,'A-4'),(8,'E-5'),(16,'C-5'),(24,'A-4'),(32,'F-4'),(40,'C-5'),(48,'A-4'),(56,'E-5')]:
        bell_row(T,r,n,vol=30)
    bass_bar(T,2,'C',vol=34,style='sparse'); bass_bar(T,3,'G',vol=34,style='sparse')
    hat_bar(T,2,'sparse',vol=16); hat_bar(T,3,'sparse',vol=18)
    riser_row(T,48,vol=26)
    fill(T,3,'toms',vol=34,start=12)
    pats.append(T.p)

    # P5 A full
    T=Tr()
    for b,ch in enumerate(PROG_A):
        pad_bar(T,b,ch,vol=30); bass_bar(T,b,ch,vol=46,style='push' if b==1 else '8ths')
        arp_bar(T,b,ch,vol=24,inst=INS['arp'])
        arp_bar(T,b,ch,vol=16,mode='up',ch=CH['arp2'],octv=1,inst=INS['arp2'])
        drums(T,b,'four','8ths')
    crash_row(T,0,vol=36); crash_row(T,32,vol=28)
    lead_phrase(T,themeA(),vol=54,vib=[(6,0x44),(24,0x44),(40,0x44),(56,0x44)])
    fill(T,3,'mix',vol=42)
    pats.append(T.p)

    # P6 B peak
    T=Tr()
    for b,ch in enumerate(PROG_B):
        pad_bar(T,b,ch,vol=32); bass_bar(T,b,ch,vol=46)
        arp_bar(T,b,ch,vol=22); arp_bar(T,b,ch,vol=15,mode='down',ch=CH['arp2'],octv=1,inst=INS['arp2'])
        drums(T,b,'push' if b in (1,3) else 'four','16ths' if b in (1,3) else '8ths')
    crash_row(T,0,vol=36); crash_row(T,32,vol=30)
    lead_phrase(T,themeB_var(),vol=54)
    fill(T,3,'snare16',vol=40,start=8)
    pats.append(T.p)

    # P7 A final chorus with hook harmony
    T=Tr()
    for b,ch in enumerate(PROG_A):
        pad_bar(T,b,ch,vol=32); bass_bar(T,b,ch,vol=48,style='drive' if b==1 else '8ths')
        arp_bar(T,b,ch,vol=20); arp_bar(T,b,ch,vol=15,mode='up',ch=CH['arp2'],octv=1,inst=INS['arp2'])
        drums(T,b,'push' if b else 'four','16ths')
    crash_row(T,0,vol=36); crash_row(T,32,vol=30)
    lead_phrase(T,themeA_var(),inst=INS['lead2'],vol=54)
    # harmony in 3rds below on lead2? use arp channel for octave stabs
    fill(T,3,'mix',vol=44)
    pats.append(T.p)

    # P8 OUTRO / turnaround
    T=Tr()
    progO=['Am','F','C','G']
    for b,ch in enumerate(progO):
        pad_bar(T,b,ch,vol=32 if b<3 else 34)
        if b<3: bass_bar(T,b,ch,vol=42,style='8ths' if b!=1 else 'push')
        arp_bar(T,b,ch,vol=20 if b<3 else 16,mode='updown')
    for b in (0,1,2):
        kick_bar(T,b,[0,8],vol=40); snare_bar(T,b,[4,12],vol=34); hat_bar(T,b,'8ths',vol=24)
    crash_row(T,0,vol=32)
    for i,(r,n) in enumerate([(0,'E-6'),(2,'D-6'),(4,'C-6'),(6,'B-5'),(8,'A-5'),(10,'G-5'),(12,'A-5'),(14,'B-5'),
                              (16,'C-6'),(18,'B-5'),(20,'A-5'),(22,'G-5'),(24,'F-5'),(26,'A-5'),(28,'C-6'),(30,'B-5'),
                              (32,'G-5'),(34,'E-5'),(36,'G-5'),(38,'A-5'),(40,'B-5'),(42,'C-6'),(44,'D-6'),(46,'E-6')]):
        T.note(r,CH['lead'],n,INS['lead'],46)
        T.note(r+3,CH['echo'],n,INS['echo'],30)
    # bar 4: rising 16ths + final Am hit, ending with fill into the loop
    for i,(r,n) in enumerate([(48,'A-5'),(49,'B-5'),(50,'C-6'),(51,'D-6'),(52,'E-6'),(53,'F-6'),(54,'G-6'),(55,'A-6'),
                              (56,'A-5'),(58,'C-6'),(60,'E-6'),(62,'A-6')]):
        T.note(r,CH['lead'],n,INS['lead'],50 if i<8 else 46)
    for i,n in enumerate(['A-4','C-5','E-5','A-5','C-6','E-6','A-6']):
        bell_row(T,56+i,n,vol=26)
    fill(T,3,'snare16',vol=42,start=12)
    crash_row(T,48,vol=30)
    pats.append(T.p)

    for p in pats: xm.add_pattern(p)
    xm.order=list(range(len(pats)))
    for I in ins:
        xm.add_instrument([dict(data=I['data'],name=I['name'],volume=I['vol'],panning=I['pan'],finetune=0,
                                relnote=I['relnote'],loop=((0,len(I['data'])) if I['loop'] else None),bits=16)],I['name'])
    return xm

if __name__=='__main__':
    xm=build()
    L,R=render_xm(xm,'f2')
    print('dur %.2f peak %.3f rms %.4f corr %.3f'%(len(L)/44100,max(np.abs(L).max(),np.abs(R).max()),np.sqrt(((L**2).mean()+(R**2).mean())/2),np.corrcoef(L,R)[0,1]))
