import sys; sys.path.insert(0,'/workspace/work')
import numpy as np, json, os
import synth2 as S2
import final4 as F
from final4 import *

RATE=16726.0; DRATE=33452.0; F0=261.6256

# ---------- custom instrument set: fewer harmonics to limit aliasing at high notes ----------
def make_data():
    ins=[]
    def add(name,data,relnote,loop=False):
        ins.append(dict(name=name,data=data,relnote=relnote,loop=loop))
    add('lead',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.25,nharm=14,cycles=32,amp=0.92),12,True)
    add('leadR', S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=11,cycles=48,amp=0.85),12,True)
    add('lead2', S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=12,cycles=40,amp=0.88),12,True)
    add('echo',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.25,nharm=9,cycles=32,amp=0.85),12,True)
    add('arpL',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=8,cycles=48,amp=0.8),12,True)
    add('arpR',  S2.pulse_loop(rate=RATE,f0=F0,duty=0.125,nharm=8,cycles=48,amp=0.8),12,True)
    add('spark', S2.pulse_loop(rate=RATE,f0=F0,duty=0.0625,nharm=6,cycles=96,amp=0.65),12,True)
    add('bass',  S2.bass_oneshot(rate=RATE,f0=F0,dur=0.42,amp=0.95,decay=0.17),12)
    add('kick',  S2.kick(rate=RATE,dur=0.34,f0=195,f1=48,decay=0.10,click=0.55),12)
    add('snare', S2.snare(rate=RATE,dur=0.24,tone=200),12)
    add('hatC',  S2.hat(rate=DRATE,dur=0.05,decay=0.011,fc=7600),24)
    add('hatO',  S2.openhat(rate=DRATE,dur=0.24,decay=0.055,fc=6400),24)
    add('crash', S2.crash(rate=DRATE,dur=1.4,decay=0.42),24)
    add('tom',   S2.tom(rate=RATE,dur=0.26,f0=340,f1=140),12)
    add('rim',   S2.zap(rate=RATE,dur=0.09,amp=0.6),12)
    add('riser', S2.riser(rate=RATE,dur=1.7),12)
    add('bell',  S2.bell(rate=RATE,f=F0,dur=1.1,amp=0.7),12)
    for ch,(root,ivs) in PADS.items():
        add('pad'+ch+'L', S2.pad(root,ivs,rate=RATE,dur=1.50,amp=0.72,det=0.0040),12)
        add('pad'+ch+'R', S2.pad(root,ivs,rate=RATE,dur=1.50,amp=0.72,det=-0.0052),12)
    return ins

# solved group gains from band analysis
G=json.load(open('work/solved_gains.json'))
INST=dict(lead=['lead','leadR','lead2'], echo=['echo'], arp=['arpL','arpR'], bass=['bass'],
          kick=['kick'], snare=['snare'], hats=['hatC','hatO'], pad=['padL','padR'],
          fx=['crash','riser','bell'], perc=['tom','rim'], spark=['spark'])
MASTER=0.62
def apply_gains():
    F.GAIN.clear()
    for grp,names in INST.items():
        for nm in names:
            g=G[grp]*(0.62 if nm=='leadR' else 1.0)
            if nm=='bell': g*=1.5
            F.GAIN[nm]=g*MASTER
    F._CACHE.clear()
    F._CACHE['data']=make_data()
    json.dump({k:float(v) for k,v in F.GAIN.items()},open('work/gaindata.json','w'))

# ---------- structure tweaks ----------
def build_song():
    apply_gains()
    xm=F.build()
    # 1) outro last chord: Am (loops into intro Am)
    # F.build() already builds P9 with PROG_O = Am F C G; patch that pattern's pad/bass/arp rows 48-63.
    p9=xm.patterns[9]
    for (r,ch) in list(p9.cells):
        if r>=48: del p9.cells[(r,ch)]
    # pad Am on row 48
    p9.cells[(48,CH['padL'])]={'note':N('C-4'),'inst':INS['padAmL'],'vol':46}
    p9.cells[(48,CH['padR'])]={'note':N('C-4'),'inst':INS['padAmR'],'vol':46}
    # bass A-2 on row 48 (short), plus bell chord
    p9.cells[(48,CH['bass'])]={'note':N('A-2'),'inst':INS['bass'],'vol':56}
    for i,n in enumerate(['A-5','C-6','E-6','A-6','C-7']):
        p9.cells[(48+i*2,CH['fx2'])]={'note':N(n),'inst':INS['bell'],'vol':34}
    # closing lead figure over Am, ending on a pickup that leads into the intro
    for r,n,v in [(48,'A-5',56),(52,'C-6',52),(56,'E-6',58),(58,'A-6',60),(61,'E-6',50),(62,'D-6',48),(63,'C-6',50)]:
        p9.cells[(r,CH['lead'])]={'note':N(n),'inst':INS['lead'],'vol':v}
    p9.cells[(56,CH['harm'])]={'note':N('C-5'),'inst':INS['leadR'],'vol':40}
    p9.cells[(58,CH['harm'])]={'note':N('E-5'),'inst':INS['leadR'],'vol':40}
    p9.cells[(48,CH['echo'])]={'note':N('A-5'),'inst':INS['echo'],'vol':26}
    p9.cells[(56,CH['kick'])]={'note':N('C-4'),'inst':INS['kick'],'vol':60}
    p9.cells[(56,CH['snare'])]={'note':N('C-4'),'inst':INS['snare'],'vol':52}
    p9.cells[(56,CH['fx'])]={'note':N('C-4'),'inst':INS['crash'],'vol':46}
    p9.cells[(56,CH['hats'])]={'note':N('C-4'),'inst':INS['hatC'],'vol':48}

    # 2) richer intro: raise pad/bell volumes and add a riser at the very start
    p0=xm.patterns[0]
    for (r,ch),c in list(p0.cells.items()):
        if 'vol' in c:
            if ch in (CH['padL'],CH['padR']): c['vol']=min(64,c['vol']+8)
            elif ch==CH['fx2']: c['vol']=min(64,c['vol']+14)
            elif ch in (CH['arpL'],CH['arpR']): c['vol']=min(64,c['vol']+10)
            elif ch==CH['hats']: c['vol']=min(64,c['vol']+8)
            elif ch==CH['kick']: c['vol']=min(64,c['vol']+8)
            elif ch==CH['snare']: c['vol']=min(64,c['vol']+8)
    # add a soft reverse-riser-ish bell arpeggio on bar 0
    for i,n in enumerate(['A-4','C-5','E-5','A-5','C-6','E-6','A-6']):
        p0.cells[(i*2,CH['fx2'])]={'note':N(n),'inst':INS['bell'],'vol':26+i*3}
    # arp in bar 0
    for i in range(0,16,2):
        seq=['A-4','C-5','E-5','A-5']
        ch=CH['arpL'] if i%2==0 else CH['arpR']
        p0.cells[(i,ch)]={'note':N(seq[(i//2)%4]),'inst':INS['arpL'] if ch==CH['arpL'] else INS['arpR'],'vol':40}

    # 3) hat panning motion in all patterns
    for p in xm.patterns:
        for r in range(0,64,4):
            key=(r,CH['hats'])
            if key not in p.cells:
                p.cells[key]={'eff':0x08,'par':0x58 if (r//4)%2==0 else 0xA8}
    return xm

if __name__=='__main__':
    xm=build_song()
    xm.save('work/f6.xm')
    L,R=render_xm(xm,'f6')
    print('peak %.3f rms %.4f corr %.3f side/mid %.3f'%(max(np.abs(L).max(),np.abs(R).max()),
        np.sqrt(((L**2).mean()+(R**2).mean())/2),np.corrcoef(L,R)[0,1],
        np.sqrt((((L-R)/2)**2).mean())/np.sqrt((((L+R)/2)**2).mean())))
    print('dur %.2f'%(len(L)/44100))
PY
