    for p in xm.patterns:
        for r in range(0,64,4):
            key=(r,CH['hats'])
            if key not in p.cells:
                p.cells[key]={'eff':0x08,'par':0x58 if (r//4)%2==0 else 0xA8}
    return xm

if __name__=='__main__':
