    p9.cells[(48,CH['padR'])]=dict(padHit,inst=INS['padAmR'])
    p9.cells[(48,CH['bass'])]={'note':N('A-2'),'inst':INS['bass'],'vol':58}
    p9.cells[(48,CH['kick'])]={'note':N('C-4'),'inst':INS['kick'],'vol':60}
    p9.cells[(48,CH['snare'])]={'note':N('C-4'),'inst':INS['snare'],'vol':52}
    p9.cells[(48,CH['fx'])]={'note':N('C-4'),'inst':INS['crash'],'vol':44}
    p9.cells[(48,CH['hats'])]={'note':N('C-4'),'inst':INS['hatC'],'vol':50}
    for i,n in enumerate(['A-4','C-5','E-5','A-5']):
        p9.cells[(48+i,CH['fx2'])]={'note':N(n),'inst':INS['bell'],'vol':34+i*3}
    # lead: resolve down and finish with a short pickup note
    for r,n,dur,v in [(48,'A-5',4,58),(52,'E-5',2,50),(54,'G-5',2,52),(56,'A-5',4,56),(61,'C-6',1,52),(62,'B-5',1,48),(63,'A-5',1,50)]:
        p9.cells[(r,CH['lead'])]={'note':N(n),'inst':INS['lead'],'vol':v}
        if dur: p9.cells[(r+dur,CH['lead'])]={'note':97}
    p9.cells[(48,CH['harm'])]={'note':N('E-5'),'inst':INS['leadR'],'vol':40}
    p9.cells[(52,CH['harm'])]={'note':97}
    p9.cells[(56,CH['harm'])]={'note':N('C-5'),'inst':INS['leadR'],'vol':38}
    p9.cells[(60,CH['harm'])]={'note':97}
    p9.cells[(48,CH['echo'])]={'note':N('A-5'),'inst':INS['echo'],'vol':28}
    p9.cells[(52,CH['echo'])]={'note':N('E-5'),'inst':INS['echo'],'vol':22}
    # last bar: gentle toms fill and no sustained crash
    for i,(r,n,v) in enumerate([(56,'C-4',50),(58,'E-4',46),(60,'G-4',48),(62,'C-4',52)]):
        p9.cells[(r,CH['perc'])]={'note':N(n),'inst':INS['tom'],'vol':v}

    # ---- hat panning animation everywhere ----
    for p in xm.patterns:
        for r in range(0,64,4):
            key=(r,CH['hats'])
            if key not in p.cells:
                p.cells[key]={'eff':0x08,'par':0x58 if (r//4)%2==0 else 0xA8}
    return xm

if __name__=='__main__':
    xm=build_song()
    xm.save('work/f7.xm')
    L,R=render_xm(xm,'f7')
