import sys; sys.path.insert(0,'/workspace/work')
import numpy as np
import synth2 as S2
# Test: generate the same instruments at lower rates; check max abs diff after 16-bit quantization
def maxdiff(d):
    q=np.clip(np.round(d*32767),-32768,32767)
    return int(np.abs(np.diff(q)).max())
tests={}
for rate_half,rel in [(33452,24),(16726,36),(8363,48)]:
    tests['hatC@%d rel%d'%(rate_half,rel)] = S2.hat(rate=rate_half,dur=0.05,decay=0.011,fc=min(7600,rate_half*0.45))
    tests['hatO@%d rel%d'%(rate_half,rel)] = S2.openhat(rate=rate_half,dur=0.24,decay=0.055,fc=min(6400,rate_half*0.45))
    tests['snare@%d rel%d'%(rate_half,rel)] = S2.snare(rate=rate_half,dur=0.24,tone=200*(rate_half/33452)**1)
    tests['crash@%d rel%d'%(rate_half,rel)] = S2.crash(rate=rate_half,dur=1.4,decay=0.42)
    tests['riser@%d rel%d'%(rate_half,rel)] = S2.riser(rate=rate_half,dur=1.7)
for k,v in tests.items():
    print('%-22s maxdiff %6d %s'%(k,maxdiff(v),'OK' if maxdiff(v)<=32000 else 'OVERFLOW'))
PY"}

